<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { admin, err, type ModelPreset, type ModelSettings, type ProbeResult, type Run, type Source, type Usage } from "./api";
import BatchProbe from "./BatchProbe.vue";
import AdminMaintenance from "./AdminMaintenance.vue";
import ContentWorkbench from "./ContentWorkbench.vue";
import { translate as tr } from "./locale";
import { adminRequestGeneration } from "./admin-state";
import { at, adminMessage, adminError, adminUsageValue as usageValue, adminRecordedUsage as recordedUsage, type AdminMessage } from "./admin-locale";
import { formatDate } from "./locale";
import { idempotentSubmission } from "./submission";

const authenticated = ref(false), csrf = ref(""), expiresAt = ref(""), password = ref(""), activeTab = ref<"sources" | "runs" | "content" | "model" | "maintenance">("sources");
const loginLoading = ref(false), loginError = ref<ReturnType<typeof err>>(), notice = ref<AdminMessage>("");
const sources = ref<Source[]>([]), runs = ref<Run[]>([]), model = ref<ModelSettings>(), usage = ref<Usage>(), presets = ref<ModelPreset[]>([]);
const batchBusy = ref(false), loading = ref(false), actionId = ref(""), pageError = ref<ReturnType<typeof err>>(), modelError = ref<ReturnType<typeof err>>();
const sourceDraft = ref({ name: "", feed_url: "", channel_type: "rss" }), editingId = ref<string | null>(null), editDraft = ref({ name: "", feed_url: "" });
const selectedSourceIds = ref<string[]>([]), apiKey = ref(""), maxTokens = ref(1024), modelEnabled = ref(false), testResult = ref<AdminMessage>(""), testTranscript = ref<{ request: Array<{ role: string; content: string }>; response: string; error: string }>(), selectedPreset = ref("custom"), providerDraft = ref(""), baseUrlDraft = ref(""), modelDraft = ref(""), submission = idempotentSubmission();
const requests = adminRequestGeneration();
watch([baseUrlDraft, modelDraft], () => { apiKey.value = ""; });
const busy = computed(() => Boolean(actionId.value) || loading.value || batchBusy.value);
const selectableSources = computed(() => sources.value.filter((source) => source.enabled && source.channel_type === "rss"));
const formatTime = (value?: string | null) => formatDate(value, { dateStyle: "short", timeStyle: "short" });
const healthLabel = (value: string) => at(({ healthy: "健康", rate_limited: "受限", unverified: "未验证", degraded: "异常", failed: "失败", unhealthy: "异常", unknown: "未知" }[value.toLowerCase()] ?? at("未知（{value}）", { value })));
const purposeLabel = (value: string) => at(({ event_extraction: "事件提取", answer_generation: "研究问答", admin_test: "后台测试", connectivity: "连接检查", completion: "回答测试", extraction: "内容提取", embedding: "向量生成" }[value.toLowerCase()] ?? at("其他用途（{value}）", { value })));
const runStatusLabel = (value: string) => at(({ queued: "排队中", partial: "部分完成", completed: "已完成", failed: "失败", running: "进行中", success: "已完成", cancelled: "已取消" }[value.toLowerCase()] ?? "未知状态"));
const runErrorLabel = (value?: string | null) => at(!value ? "" : value.includes("403") ? "原站拒绝访问，部分内容未采集。" : value.includes("429") ? "访问频繁，稍后再试。" : "本次采集未完全成功，可在详情查看原始诊断。");
const ledgerStatusLabel = (value: string) => at(({ completed: "已完成", filtered: "已筛除", extraction_failed: "提取失败", unknown: "结果未知", started: "进行中", success: "成功", succeeded: "成功", failed: "失败", pending: "等待中", unavailable: "不可用" }[value.toLowerCase()] ?? at("未知（{value}）", { value })));
function clearPrivateState() { batchBusy.value = false; presets.value = []; providerDraft.value = ""; baseUrlDraft.value = ""; modelDraft.value = ""; selectedPreset.value = "custom"; csrf.value = ""; expiresAt.value = ""; password.value = ""; sources.value = []; runs.value = []; model.value = undefined; usage.value = undefined; sourceDraft.value = { name: "", feed_url: "", channel_type: "rss" }; editDraft.value = { name: "", feed_url: "" }; editingId.value = null; selectedSourceIds.value = []; apiKey.value = ""; testResult.value = ""; testTranscript.value = undefined; pageError.value = undefined; modelError.value = undefined; notice.value = ""; }
function lock(message?: string) { requests.invalidate(); authenticated.value = false; loginLoading.value = false; loading.value = false; actionId.value = ""; clearPrivateState(); if (message) loginError.value = { code: "UNAUTHORIZED", message, status: 401 }; }
function handle(e: unknown, target = pageError) { const problem = err(e); if (problem.status === 401) lock(authenticated.value ? "会话已过期，请重新输入管理口令。" : "管理口令无效。"); else target.value = problem; }
function current(generation: number) { return authenticated.value && requests.current(generation); }
async function restore() { loginLoading.value = true; const generation = requests.capture(); try { const session = await admin.session(); if (!requests.current(generation)) return; authenticated.value = session.authenticated; csrf.value = session.csrf_token ?? ""; expiresAt.value = session.expires_at ?? ""; if (session.authenticated && csrf.value) await loadAll(); } catch (e) { if (requests.current(generation)) handle(e, loginError); } finally { if (requests.current(generation)) loginLoading.value = false; } }
async function login() { if (!password.value || loginLoading.value) return; loginLoading.value = true; loginError.value = undefined; const generation = requests.capture(); try { const session = await admin.session(password.value); password.value = ""; if (!requests.current(generation)) return; if (!session.authenticated || !session.csrf_token) { lock("管理口令无效。"); return; } authenticated.value = true; csrf.value = session.csrf_token; expiresAt.value = session.expires_at ?? ""; await loadAll(); } catch (e) { password.value = ""; if (requests.current(generation)) handle(e, loginError); } finally { if (requests.current(generation)) loginLoading.value = false; } }
async function refreshSources() { if (!authenticated.value) return; const generation = requests.capture(); try { const result = await admin.sources(); if (current(generation)) sources.value = result.items; } catch (e) { if (current(generation)) handle(e); } }
function applyPreset() { const preset = presets.value.find((item) => item.id === selectedPreset.value); if (!preset) return; providerDraft.value = preset.id; baseUrlDraft.value = preset.base_url; modelDraft.value = preset.model; apiKey.value = ""; notice.value = "已填入预设。切换服务端点后需要输入新的 API 密钥并保存。"; }
async function loadAll() { if (!authenticated.value) return; loading.value = true; pageError.value = undefined; modelError.value = undefined; const generation = requests.capture(); try { const [sourceResult, runResult, settings, usageResult, presetResult] = await Promise.all([admin.sources(), admin.runs(), admin.model(), admin.usage(), admin.presets()]); if (!current(generation)) return; sources.value = sourceResult.items; runs.value = runResult.items; model.value = settings; usage.value = usageResult; presets.value = presetResult.items; maxTokens.value = settings.max_tokens; modelEnabled.value = settings.enabled; providerDraft.value = settings.provider; baseUrlDraft.value = settings.base_url; modelDraft.value = settings.model; selectedPreset.value = presetResult.items.find(p => p.id === settings.provider && p.base_url === settings.base_url && p.model === settings.model)?.id ?? "custom"; selectedSourceIds.value = selectedSourceIds.value.filter((id) => sourceResult.items.some((source) => source.id === id && source.enabled && source.channel_type === "rss")); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) loading.value = false; } }
async function createSource() { if (busy.value || !sourceDraft.value.name.trim() || !sourceDraft.value.feed_url.trim()) return; actionId.value = "create"; const generation = requests.capture(); try { await admin.createSource(csrf.value, { ...sourceDraft.value, name: sourceDraft.value.name.trim(), feed_url: sourceDraft.value.feed_url.trim() }); if (!current(generation)) return; sourceDraft.value = { name: "", feed_url: "", channel_type: "rss" }; notice.value = "来源已添加，默认处于停用状态。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
function beginEdit(source: Source) { if (!busy.value) { editingId.value = source.id; editDraft.value = { name: source.name, feed_url: source.feed_url }; } }
async function saveSource(source: Source) { if (busy.value) return; actionId.value = `save-${source.id}`; const generation = requests.capture(); try { await admin.updateSource(csrf.value, source.id, editDraft.value); if (!current(generation)) return; editingId.value = null; notice.value = "来源已保存。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function toggleSource(source: Source) { if (busy.value) return; actionId.value = `toggle-${source.id}`; const generation = requests.capture(); try { await admin.updateSource(csrf.value, source.id, { enabled: !source.enabled }); if (!current(generation)) return; notice.value = source.enabled ? "来源已停用。" : "来源已启用。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function probe(source: Source) { if (busy.value) return; actionId.value = `probe-${source.id}`; const generation = requests.capture(); try { const result: ProbeResult = await admin.probe(csrf.value, source.id); if (!current(generation)) return; notice.value = adminMessage("{name}：{message}{items}", { name: source.name, message: adminMessage(result.message), items: result.items_found === undefined ? "" : adminMessage("（发现 {count} 项）", { count: result.items_found }) }); await refreshSources(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
function toggleSelection(id: string, checked: boolean) { selectedSourceIds.value = checked ? [...selectedSourceIds.value, id] : selectedSourceIds.value.filter((value) => value !== id); }
async function startIngest() { if (busy.value || !selectedSourceIds.value.length) return; const key = submission.begin(); if (!key) return; actionId.value = "ingest"; const generation = requests.capture(); try { const result = await admin.start(csrf.value, selectedSourceIds.value, key); submission.finish(true); if (!current(generation)) return; notice.value = adminMessage("已接受采集请求：{id}", { id: result.run_id }); const response = await admin.runs(); if (current(generation)) runs.value = response.items; } catch (e) { submission.finish(false); if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function saveModel() { if (busy.value) return; actionId.value = "model-save"; modelError.value = undefined; const generation = requests.capture(); try { if (baseUrlDraft.value !== model.value?.base_url && !apiKey.value) { modelError.value = { code: "API_KEY_REQUIRED", message: "切换服务端点需要输入新的 API 密钥。" }; actionId.value = ""; return; }
  const payload: { api_key?: string; enabled: boolean; max_tokens: number; provider: string; base_url: string; model: string } = { enabled: modelEnabled.value, max_tokens: maxTokens.value, provider: providerDraft.value, base_url: baseUrlDraft.value, model: modelDraft.value }; if (apiKey.value) payload.api_key = apiKey.value; const saved = await admin.saveModel(csrf.value, payload); if (!current(generation)) return; apiKey.value = ""; model.value = saved; notice.value = "模型设置已保存。"; } catch (e) { if (current(generation)) handle(e, modelError); } finally { if (current(generation)) actionId.value = ""; } }
async function testModel(kind: "connectivity" | "completion") { if (busy.value) return; actionId.value = `test-${kind}`; testResult.value = ""; testTranscript.value = undefined; const generation = requests.capture(); try { const result = await admin.testModel(csrf.value, kind); if (!current(generation)) return; testResult.value = adminMessage("{status}：{message}{usage}", { status: adminMessage(result.ok ? "通过" : "未通过"), message: adminMessage(result.message), usage: result.usage ? adminMessage(" · {count} tokens", { count: result.usage.total_tokens ?? adminMessage("未知") }) : "" }); testTranscript.value = kind === "completion" ? { request: result.request_messages ?? [], response: result.response_text ?? "", error: result.error_code ?? "" } : undefined; const resultUsage = await admin.usage(); if (current(generation)) usage.value = resultUsage; } catch (e) { if (current(generation)) handle(e, modelError); } finally { if (current(generation)) actionId.value = ""; } }
async function logout() { if (busy.value) return; actionId.value = "logout"; loginError.value = undefined; const generation = requests.capture(); try { await admin.logout(csrf.value); if (!requests.current(generation)) return; lock(); } catch (e) { if (requests.current(generation)) pageError.value = { ...err(e), message: "退出未完成，当前会话仍有效，请重试。" }; } finally { if (requests.current(generation)) actionId.value = ""; } }
onMounted(() => { void restore(); });
</script>
<template>
  <section class="admin-page"><div class="admin-heading"><div><h1 class="page-title">{{ at('管理员后台') }}</h1><p class="page-subtitle">{{ at('来源、采集与模型服务只在受保护会话中可用。') }}</p></div><button v-if="authenticated" type="button" class="admin-logout" :title="at('退出管理员后台')" :aria-label="at('退出管理员后台')" :disabled="busy" @click="logout">{{ at(actionId === "logout" ? "退出中…" : "退出") }}</button></div><p v-if="notice" class="admin-notice" aria-live="polite">{{ at(notice) }}</p>
    <section v-if="!authenticated" class="admin-lock card" aria-labelledby="admin-lock-title"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v2"/></svg><div><h2 id="admin-lock-title">{{ at('需要管理员会话') }}</h2><p class="meta">{{ at('输入管理口令以开启当前浏览器会话。口令不会保存在浏览器存储中。') }}</p></div><form class="admin-login" @submit.prevent="login"><label>{{ at('管理口令') }}<input v-model="password" class="control" type="password" autocomplete="current-password" :disabled="loginLoading" /></label><button type="submit" :disabled="loginLoading || !password">{{ at(loginLoading ? "验证中…" : "进入后台") }}</button></form><div v-if="loginError" class="error admin-feedback" role="alert">{{ adminError(loginError) }}</div></section>
    <template v-else><p class="meta admin-session">{{ at('会话有效至 {time}。退出或过期后需重新验证。', { time: formatTime(expiresAt) }) }}</p><div class="admin-tabs" role="tablist" :aria-label="at('后台管理区')"><button :class="{ active: activeTab === 'sources' }" role="tab" :aria-selected="activeTab === 'sources'" :disabled="busy" @click="activeTab = 'sources'">{{ at('来源') }}</button><button :class="{ active: activeTab === 'runs' }" role="tab" :aria-selected="activeTab === 'runs'" :disabled="busy" @click="activeTab = 'runs'">{{ at('采集记录') }}</button><button :class="{ active: activeTab === 'content' }" role="tab" :aria-selected="activeTab === 'content'" :disabled="busy" @click="activeTab = 'content'">{{ tr('内容工作台', 'Content Workbench') }}</button><button :class="{ active: activeTab === 'model' }" role="tab" :aria-selected="activeTab === 'model'" :disabled="busy" @click="activeTab = 'model'">{{ at('模型设置') }}</button><button :class="{ active: activeTab === 'maintenance' }" role="tab" :aria-selected="activeTab === 'maintenance'" :disabled="busy" @click="activeTab = 'maintenance'">{{ tr('数据核查', 'Data review') }}</button></div><div v-if="pageError" class="error admin-feedback" role="alert">{{ adminError(pageError) }} <button type="button" :disabled="busy" @click="loadAll">{{ at('重试') }}</button></div><p v-if="loading" class="admin-skeleton" aria-live="polite">{{ at('正在同步管理数据…') }}</p>
      <section v-if="activeTab === 'sources' && !loading" class="admin-stack" :aria-label="at('来源管理')"><form class="card admin-form" @submit.prevent="createSource"><div><h2>{{ at('添加 RSS 来源') }}</h2><p class="meta">{{ at('新来源默认停用；探测成功后再开启采集。') }}</p></div><label>{{ at('名称') }}<input v-model="sourceDraft.name" class="control" maxlength="160" :disabled="busy" /></label><label>{{ at('订阅地址') }}<input v-model="sourceDraft.feed_url" class="control" type="url" maxlength="2048" placeholder="https://…/feed.xml" :disabled="busy" /></label><button type="submit" :disabled="busy || !sourceDraft.name || !sourceDraft.feed_url">{{ at(actionId === "create" ? "添加中…" : "添加来源") }}</button></form><BatchProbe :sources="sources" :csrf="csrf" :disabled="busy" @busy="batchBusy = $event" @complete="refreshSources" @unauthorized="lock('会话已过期，请重新输入管理口令。')" />
        <section class="card"><div class="admin-section-title"><div><h2>{{ at('来源健康') }}</h2><p class="meta">{{ at('{count} 个来源。', { count: sources.length }) }}</p></div><button type="button" :title="at('刷新来源状态')" :aria-label="at('刷新来源状态')" :disabled="busy" @click="loadAll">{{ at('刷新') }}</button></div><p v-if="!sources.length" class="empty meta">{{ at('暂无来源。添加一个 RSS 地址后可在此探测和启用。') }}</p><article v-for="source in sources" :key="source.id" class="source-row"><div class="source-main"><template v-if="editingId === source.id"><label>{{ at('名称') }}<input v-model="editDraft.name" class="control" maxlength="160" :disabled="busy" /></label><label>{{ at('订阅地址') }}<input v-model="editDraft.feed_url" class="control" type="url" maxlength="2048" :disabled="busy" /></label></template><template v-else><strong>{{ source.name }}</strong><a :href="source.feed_url" target="_blank" rel="noreferrer">{{ source.feed_url }}</a></template><p class="meta"><span class="health" :class="source.health" :title="healthLabel(source.health)">{{ healthLabel(source.health) }}</span> · {{ at('连续失败 {count} · 最近探测 {checked} · 最近成功 {success}', { count: source.consecutive_failures, checked: formatTime(source.last_checked_at), success: formatTime(source.last_success_at) }) }}<span v-if="source.cooldown_until"> · {{ at('冷却至 {time}', { time: formatTime(source.cooldown_until) }) }}</span></p><p v-if="!source.editable" class="meta">{{ at('内置采集适配：名称和订阅地址由系统维护。') }}</p></div><div class="source-actions"><template v-if="editingId === source.id"><button type="button" :disabled="busy" @click="saveSource(source)">{{ at(actionId === `save-${source.id}` ? "保存中…" : "保存") }}</button><button type="button" :disabled="busy" @click="editingId = null">{{ at('取消') }}</button></template><template v-else><button v-if="source.editable" type="button" :title="at('编辑来源')" :aria-label="at('编辑 {name}', { name: source.name })" :disabled="busy" @click="beginEdit(source)">{{ at('编辑') }}</button><button type="button" :disabled="busy" :title="at('探测 {name}', { name: source.name })" @click="probe(source)"><svg v-if="actionId === `probe-${source.id}`" class="probe-spinner" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/></svg>{{ at(actionId === `probe-${source.id}` ? "探测中…" : "探测") }}</button><button type="button" :disabled="busy" @click="toggleSource(source)">{{ at(source.enabled ? "停用" : "启用") }}</button></template></div></article></section></section>
      <section v-if="activeTab === 'runs' && !loading" class="admin-stack"><section class="card"><div class="admin-section-title"><div><h2>{{ at('采集记录') }}</h2><p class="meta">{{ at('手动采集仅提交下方明确勾选的已启用 RSS 来源。归档适配由定时回填处理，不能在此提交。') }}</p></div><button type="button" :disabled="busy || !selectedSourceIds.length" @click="startIngest">{{ at(actionId === "ingest" ? "提交中…" : "开始采集") }}</button></div><fieldset class="source-picker"><legend>{{ at('选择要采集的 RSS 来源') }}</legend><p v-if="!selectableSources.length" class="meta">{{ at('没有可手动采集的已启用 RSS 来源。') }}</p><label v-for="source in selectableSources" :key="source.id"><input type="checkbox" :checked="selectedSourceIds.includes(source.id)" :disabled="busy" @change="toggleSelection(source.id, ($event.target as HTMLInputElement).checked)" />{{ source.name }}</label></fieldset><p v-if="!runs.length" class="empty meta">{{ at('尚无采集记录。') }}</p><div v-else class="runs-table"><article v-for="run in runs" :key="run.id"><strong :title="runStatusLabel(run.status)">{{ runStatusLabel(run.status) }}</strong><span>{{ formatTime(run.started_at) }}</span><span class="tabular">{{ at('发现 {found} · 候选 {candidates} · 版本 {versions} · 发布 {kept}', { found: run.found, candidates: run.candidates, versions: run.versions, kept: run.kept }) }}</span><span class="tabular">{{ at('解析失败 {parser} · 任务失败 {jobs}', { parser: run.parser_failures, jobs: run.failed_jobs }) }}</span><details v-if="run.error_summary" class="run-error"><summary>{{ runErrorLabel(run.error_summary) }}</summary><pre>{{ run.error_summary }}</pre></details></article></div></section></section>
      <section v-if="activeTab === 'model' && !loading && model" class="admin-stack"><section class="card admin-model"><div><h2>{{ at('模型服务配置') }}</h2><p class="meta">{{ at('支持 OpenAI Chat Completions 兼容接口；预设可继续修改，保存后生效。') }}</p><p class="meta">{{ model.provider }} · {{ model.model }} · {{ model.base_url }}</p></div><form class="admin-form" @submit.prevent="saveModel"><label>{{ at('配置方式') }}<select v-model="selectedPreset" class="control" :disabled="busy" @change="applyPreset"><option value="custom">{{ at('自定义') }}</option><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label><label>{{ at('服务商') }}<input v-model="providerDraft" class="control" :disabled="busy" /></label><label>{{ at('服务地址') }}<input v-model="baseUrlDraft" class="control" type="url" :disabled="busy" /></label><label>{{ at('模型') }}<input v-model="modelDraft" class="control" :disabled="busy" /></label><label>{{ at('新 API 密钥') }}<input v-model="apiKey" class="control" type="password" autocomplete="new-password" :placeholder="at('留空以保留当前密钥')" :disabled="busy" /></label><label>{{ at('最大输出 tokens') }}<input v-model.number="maxTokens" class="control" type="number" min="1" max="2000" :disabled="busy" /></label><label class="toggle"><input v-model="modelEnabled" type="checkbox" :disabled="busy" />{{ at('启用模型服务') }}</label><p class="meta">{{ at(model.configured ? '当前密钥已配置，系统不会回显密钥。' : '当前密钥未配置，系统不会回显密钥。') }}</p><button type="submit" :disabled="busy">{{ at(actionId === "model-save" ? "保存中…" : "保存设置") }}</button></form><div class="model-tests"><div><h3>{{ at('连接检查') }}</h3><p class="meta">{{ at('使用已保存的配置验证服务连通与鉴权，不会生成回答。') }}</p><button type="button" :disabled="busy" @click="testModel('connectivity')">{{ at(actionId === "test-connectivity" ? "检查中…" : "检查连接") }}</button></div><div><h3>{{ at('回答测试') }}</h3><p class="meta">{{ at('使用已保存的配置请求当前模型生成一条简短回答，并记录 token 用量。') }}</p><button type="button" :disabled="busy" @click="testModel('completion')">{{ at(actionId === "test-completion" ? "测试中…" : "测试回答") }}</button></div></div><p v-if="testResult" class="admin-notice" aria-live="polite">{{ at(testResult) }}</p><section v-if="testTranscript" class="model-transcript" :aria-label="at('模型测试对话')"><h3>{{ at('测试对话') }}</h3><p v-for="message in testTranscript.request" :key="message.role + message.content"><strong>{{ at(message.role === "user" ? "请求" : "系统") }}：</strong>{{ message.content }}</p><p v-if="testTranscript.response"><strong>{{ at('返回：') }}</strong>{{ testTranscript.response }}</p><p v-if="testTranscript.error" class="error"><strong>{{ at('错误：') }}</strong>{{ testTranscript.error }}</p></section><div v-if="modelError" class="error admin-feedback" role="alert">{{ adminError(modelError) }}</div></section><section class="card"><h2>{{ at('模型用量') }}</h2><p class="meta">{{ at('截至 {time}', { time: formatTime(usage?.as_of) }) }}</p><p v-if="!usage?.items.length" class="empty meta">{{ at('暂无可记录的模型调用。') }}</p><div v-else class="usage-table"><article v-for="item in usage.items" :key="`${item.purpose}-${item.status}`"><strong :title="purposeLabel(item.purpose)">{{ purposeLabel(item.purpose) }}</strong><span :title="ledgerStatusLabel(item.status)">{{ ledgerStatusLabel(item.status) }} · {{ at('{count} 次', { count: item.calls }) }}</span><span class="tabular">{{ at('输入 {input} · 输出 {output} · 合计 {total}', { input: usageValue(item.input_tokens), output: usageValue(item.output_tokens), total: usageValue(item.total_tokens) }) }}</span><span>{{ recordedUsage(item.usage_recorded) }}</span></article></div></section></section>
      <ContentWorkbench v-if="activeTab === 'content' && !loading" :csrf="csrf" @unauthorized="lock('会话已过期，请重新输入管理口令。')" />
      <AdminMaintenance v-if="activeTab === 'maintenance'" :csrf="csrf" @unauthorized="lock('会话已过期，请重新输入管理口令。')" />
    </template></section>
</template>